Begin ColonyMineDoor

;enables door and controls entry to mine during quest CO_2


if ( GetDisabled == 0 )
	if ( ColonyState < 1 )
		Disable
	endif
endif

if ( GetDisabled == 1 )
	if ( ColonyState >= 2 )
		Enable
	endif
endif

if ( GetJournalIndex CO_2 >= 10 )
	if ( GetJournalIndex CO_2 < 50 )
		if ( GetDistance "Hroldar the Strange" <= 256 )
			If ( OnActivate == 1 )
				MessageBox "A porta não pode ser aberta. Hroldar está bloqueando o caminho."
			endif
		endif
	endif
endif

if ( GetJournalIndex CO_2 >= 50 )
	if ( OnActivate == 1 )
		Activate
	endif
endif

End ColonyDoorMine

Begin stoneUlfgarScript

if ( menumode == 1 )
	return
endif

if ( GetJournalIndex "BM_BrodirGrove" < 90 )
	Disable
endif

if ( GetJournalIndex "BM_BrodirGrove" >= 90 )
		Enable
endif


if ( GetJournalIndex BM_BrodirGrove < 90 )
	return
endif


if ( OnActivate == 1 )
	if ( GetJournalIndex BM_BrodirGrove >= 10 )
		Cast "stone_ulfgar" Player					;fortify strength 10
		MessageBox "Você recebeu o dom da força de Ulfgar."
	endif
endif

end
